CREATE TABLE "product_category_settings" ("id" TEXT NOT NULL, "organization_id" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "product_category_settings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "tax_categories" ("id" TEXT NOT NULL, "organization_id" TEXT NOT NULL, "name" TEXT NOT NULL, "rate" DECIMAL(5,2) NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "tax_categories_pkey" PRIMARY KEY ("id"));
ALTER TABLE "products" ADD COLUMN "custom_category_id" TEXT, ADD COLUMN "purchase_price" DECIMAL(12,2) NOT NULL DEFAULT 0, ADD COLUMN "selling_price" DECIMAL(12,2) NOT NULL DEFAULT 0, ADD COLUMN "tax_category_id" TEXT;
CREATE UNIQUE INDEX "product_category_settings_organization_id_code_key" ON "product_category_settings"("organization_id", "code"); CREATE UNIQUE INDEX "tax_categories_organization_id_name_key" ON "tax_categories"("organization_id", "name");
ALTER TABLE "product_category_settings" ADD CONSTRAINT "product_category_settings_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "tax_categories" ADD CONSTRAINT "tax_categories_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "products" ADD CONSTRAINT "products_custom_category_id_fkey" FOREIGN KEY ("custom_category_id") REFERENCES "product_category_settings"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "products" ADD CONSTRAINT "products_tax_category_id_fkey" FOREIGN KEY ("tax_category_id") REFERENCES "tax_categories"("id") ON DELETE SET NULL ON UPDATE CASCADE;
